CREATE TABLE tfda_import_guard(ok INTEGER CHECK(ok=1));
INSERT INTO tfda_import_guard SELECT CASE WHEN (SELECT COUNT(*) FROM nutrition_foods)=2213 AND (SELECT SUM(nutrient_count) FROM nutrition_foods)=230152 AND (SELECT COUNT(*) FROM nutrition_nutrient_data)=2213 THEN 1 ELSE 0 END;
DROP TABLE tfda_import_guard;
